{
  "window_id": "w0030",
  "observed_failures": [
    {
      "id": "F1",
      "filename": "078.jpg",
      "symptom": "total_amount written as empty string \"\" instead of a real null cell",
      "evidence": "predictions row for 078.jpg has total_amount=\"\"; task contract specifies null on extraction failure"
    },
    {
      "id": "F2",
      "filename": "077.jpg",
      "symptom": "total_amount=23.26 picked from 'Total (Inclusive of GST):' line instead of the final 'TOTAL: 23.25' line after rounding adjustment",
      "evidence": "Banh Mi CafE receipt shows Total (Inclusive of GST):23.26, Rounding Adj:-0.01, TOTAL:23.25; prediction took the non-final rounded total"
    },
    {
      "id": "F3",
      "filename": "074.jpg",
      "symptom": "total_amount=702.00 instead of 92.80 even though a higher-quality OCR pass (3x upscale + PSM 4) correctly recovered 'Grand Total 92.80'",
      "evidence": "Thai Delicious Restaurant receipt shows Grand Total 92.80; source-run think log notes the 3x+PSM4 variant recovered 92.80, but the aggregated/voted extraction still returned 702.00"
    },
    {
      "id": "F4",
      "filename": "034.jpg",
      "symptom": "date=2018-08-09 instead of 2018-03-09 (receipt date '09/03/2018')",
      "evidence": "Perniagaan Zheng Hui receipt header: 'Date: 09/03/2018'; 'Time: 08:49:00' is present as a nearby token, and OCR digit confusion (03 vs 08) is a plausible source of the day/month substitution"
    }
  ],
  "root_causes": [
    {
      "id": "RC1",
      "description": "Null-value contract not enforced at the writer boundary: empty strings leak through for failed extractions, violating the 'null on failure' requirement.",
      "related_failures": ["F1"]
    },
    {
      "id": "RC2",
      "description": "Within-tier tiebreak for TOTAL keyword picks the FIRST matching line encountered. When multiple lines in the same tier qualify (e.g., 'Total (Inclusive of GST):' and 'TOTAL:'), the unqualified/final TOTAL line (typically the bottom-most, post-rounding value) is overridden by an earlier, pre-adjustment line.",
      "related_failures": ["F2"]
    },
    {
      "id": "RC3",
      "description": "Multi-pass OCR output is concatenated into a single blob before keyword/number extraction. This lets a lower-quality pass inject wrong digits into the SAME keyword line as a higher-quality pass, and the first-match rule then selects the corrupted number.",
      "related_failures": ["F3"]
    },
    {
      "id": "RC4",
      "description": "Date extraction scans all date-shaped tokens in reading order without anchoring to a 'Date'/'DATE' label, so OCR digit confusion in nearby non-date tokens (times, transaction numbers) can produce plausible-looking but wrong dates.",
      "related_failures": ["F4"]
    },
    {
      "id": "RC5",
      "description": "Preprocessing/variant set is small and generic; it lacks a digit-focused rescue pass (character whitelist, additional PSM-7 single-line crop around total keyword) that reliably recovers money amounts on faint/low-contrast receipts.",
      "related_failures": ["F3"]
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "extract_total returns the first keyword-matching line within a tier; no tiebreak for qualified vs unqualified TOTAL, nor for 'last match wins' (post-rounding final)."
    },
    {
      "skill": "image-ocr",
      "defect": "multi_pass_ocr concatenates all variant outputs; extract_total then sees a mixed text where corrupted and clean versions of the same line coexist. No per-pass extraction + consensus is defined."
    },
    {
      "skill": "image-ocr",
      "defect": "extract_date has no label-proximity preference and no sanity filter (e.g., prefer dates on or immediately after a line containing 'Date', 'DATE', 'Tarikh', or an ISO/receipt header)."
    },
    {
      "skill": "image-ocr",
      "defect": "Preprocessing recipe does not include a digit-focused rescue path (character whitelist, PSM-7 on a cropped band near the total keyword) for faint monetary totals."
    },
    {
      "skill": "xlsx",
      "defect": "Strict-schema guidance mentions nulls but does not require a final writer-side normalization step that coerces empty strings / 'nan' / 'None' to real None before to_excel."
    }
  ],
  "repair_recommendations": [
    {
      "skill": "image-ocr",
      "change": "Refine extract_total tier matching: (a) within a tier, collect ALL candidate (line, number) hits, then rank by (i) line is NOT qualified by parentheses or words like 'Inclusive', 'Excluding', 'Excl', 'Incl', 'Rounded', (ii) line appears LATER in the receipt (bottom-up preference, since final total typically follows rounding), (iii) number magnitude is consistent with earlier subtotal if available. Document the bottom-up tiebreak explicitly.",
      "generalization": "Applies to any receipt with both a GST-inclusive total and a post-rounding final total."
    },
    {
      "skill": "image-ocr",
      "change": "Change multi_pass_ocr to return a list of per-variant texts (not a joined string). In structured extraction, run extract_total and extract_date on EACH variant independently, then vote: pick the value returned by the highest-priority tier across variants, breaking ties by frequency, then by variant-quality order (upscale+PSM4 > upscale+PSM6 > autocontrast+PSM6 > default).",
      "generalization": "Prevents cross-variant digit contamination for any noisy scan."
    },
    {
      "skill": "image-ocr",
      "change": "Add a digit-rescue pass to the variant list: 3x LANCZOS upscale + grayscale autocontrast + PSM 4 or PSM 6 with tessedit_char_whitelist including digits, '.', ',', 'RM', ':', and spaces. Use this variant's result only to resolve numeric fields (total), not full text.",
      "generalization": "Improves amount recovery on all faint printed receipts."
    },
    {
      "skill": "image-ocr",
      "change": "Harden extract_date: (a) first search lines whose uppercase form contains 'DATE' or 'TARIKH' and take the first valid date on that line or the next non-empty line; (b) fall back to the whole-text scan only if label-anchored search fails; (c) reject matches whose year is implausible (e.g., outside a reasonable window) or whose source token is clearly a time (contains ':').",
      "generalization": "Reduces mis-parses from OCR digit noise or time-of-day tokens on any dated document."
    },
    {
      "skill": "image-ocr",
      "change": "Explicitly state the per-image null-safe contract: on any exception OR when extract_total/extract_date return None, the pipeline must still emit a row with Python None (never '', 'None', 'NaN', 0, or 0.0) for the missing field.",
      "generalization": "Applies to any batch extraction task graded on real nulls."
    },
    {
      "skill": "xlsx",
      "change": "Add a mandatory writer-side normalization step in the strict-schema canonical pattern: before to_excel, replace '', 'None', 'NaN', 'nan', and pd.NA with None for every string column; assert no empty strings remain in nullable fields. Include a post-write re-read assertion that any non-null total_amount matches r'^\\d+\\.\\d{2}$' and any non-null date matches r'^\\d{4}-\\d{2}-\\d{2}$'.",
      "generalization": "Protects any line-by-line graded Excel output from empty-string and format drift."
    },
    {
      "skill": "xlsx",
      "change": "In the Pitfalls section, add an explicit example showing that writing '' for a failed extraction produces a cell equal to the empty string (not a null) and will fail cell-by-cell grading; show the corrective pattern using None.",
      "generalization": "Reinforces null semantics for all future strict-schema tasks."
    }
  ],
  "confidence": {
    "overall": 0.78,
    "notes": "F1 (null leak) and F2 (within-tier TOTAL ordering) are directly reproducible from the predictions and the visible receipt text. F3 root cause is strongly suggested by the source think-log fragment indicating the 3x+PSM4 variant recovered the correct amount while the final prediction did not, consistent with concatenated-text contamination. F4 root cause is inferred: the specific OCR corruption that produced 2018-08-09 is not directly visible, but the proposed label-anchored date extraction mitigates the general failure mode without needing the exact digit confusion to be confirmed."
  }
}
